--   PROMPT: the W1 open-book label goes; keys, expected values and tolerances stay.
--
-- ADVANCED (pick B: strip)
--   Section 3 pick B: no advanced value prints on a panel's opening state or in
--   a lesson (every field is a select or a mode away); the W1 label and lesson
--   note go. Keys unchanged.
--   PROMPT: the W1 open-book label goes; keys, expected values and tolerances stay.
--
-- WHAT DOES NOT MOVE. The title, status and the row itself; on a pick B tier
-- also every field (key, label, unit, expected, tol and position) and the
-- dataset.
--
-- ATTEMPTS. Tiers this file re-keys: welltest/beginner. Before it writes, the
-- file counts academy_capstone_attempts on each and REFUSES if any exist,
-- unless D5 allowlists that tier with the exact attempt ids (allowlist:
-- {"petrophysics/beginner": ["4d4e7c7b-5907-44fd-b79a-db381bfefb7b",
-- "85712d45-1ea6-4b3e-a2fe-add4f23e8bd1",
-- "fd1e594d-4963-4ddf-abdf-0bf375c9aa26",
-- "6ab22d5e-b5e0-4bd6-aa92-3d529d5e175e"], "welldata/beginner":
-- ["494f7d7d-af88-48f9-abaa-683d922164a7",
-- "09b0d455-b4a5-4cb8-b9c0-b22e12d2ae54",
-- "dfa55a33-f21f-44ef-8d90-56bef52c47fa",
-- "b8fc9345-4063-4dc8-bf4c-8e3f57a68144",
-- "1d3834e3-ce9a-44ce-88c1-458e082067ad",
-- "f5e4dfe0-f46d-43f2-a26c-ac5087efcc8f",
-- "0a216e47-7970-4e0a-9ac6-18c7094469b6"]}). Stored scores are never touched.
--
-- GUARDS. Each row must hold EITHER its post-W1 prompt and dataset (by md5)
-- and fields (exact jsonb), as production holds them after the W1 34 files
-- (it is rewritten), OR its W5 form (left alone). Anything else raises and the
-- whole file rolls back. Lessons and panels ship with the NextGen zip, near-
-- simultaneous with this apply. Generated by
-- docs/graded-field-audit/w5c_capstones.py. SAFE TO RE-RUN: a second run
-- writes nothing.
-- ============================================================================

do $$
declare
  v_n        integer;
  v_count    integer;
  v_written  integer := 0;
  v_ids      jsonb;
  v_extra    jsonb;
  v_idtxt    text;
  v_allow    jsonb := '{"petrophysics/beginner": ["4d4e7c7b-5907-44fd-b79a-db381bfefb7b", "85712d45-1ea6-4b3e-a2fe-add4f23e8bd1", "fd1e594d-4963-4ddf-abdf-0bf375c9aa26", "6ab22d5e-b5e0-4bd6-aa92-3d529d5e175e"], "welldata/beginner": ["494f7d7d-af88-48f9-abaa-683d922164a7", "09b0d455-b4a5-4cb8-b9c0-b22e12d2ae54", "dfa55a33-f21f-44ef-8d90-56bef52c47fa", "b8fc9345-4063-4dc8-bf4c-8e3f57a68144", "1d3834e3-ce9a-44ce-88c1-458e082067ad", "f5e4dfe0-f46d-43f2-a26c-ac5087efcc8f", "0a216e47-7970-4e0a-9ac6-18c7094469b6"]}'::jsonb;  -- D5 allowlist: 'course/tier' -> attempt ids signed off
  v_s0       text;
  v_s1       text;
  v_s2       text;
begin
  -- welltest / beginner
  select count(*) into v_n from public.academy_capstones where app_slug = 'welltest' and tier = 'beginner' and active;
  if v_n <> 1 then raise exception 'w5c welltest refused: welltest/beginner has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = '5f4d6e8c2f85acf547e09db4e46cb256' and md5(dataset) = '491bfcf2f121691400ef887648ea63d8' and fields = '[{"key": "horner_k_md", "tol": 0.05, "unit": "mD", "label": "Horner permeability", "expected": 82.49005478363101}, {"key": "horner_skin", "tol": 0.005, "unit": "-", "label": "Skin from the one-hour pressure", "expected": 6.075741352818642}, {"key": "horner_slope_psi_cycle", "tol": 0.005, "unit": "psi/cycle", "label": "Semilog slope", "expected": 22.175400474615625}, {"key": "horner_pstar_psia", "tol": 0.05, "unit": "psia", "label": "Extrapolated pressure p star", "expected": 4800.151625643111}, {"key": "skin_dp_psi", "tol": 0.05, "unit": "psi", "label": "Skin pressure drop", "expected": 116.99974214185609}, {"key": "ri_at_tp_ft", "tol": 0.5, "unit": "ft", "label": "Radius of investigation at 36 h", "expected": 1269.4036637344336}]'::jsonb then 'old'
              when md5(prompt) = '959c0a681647ab6f0014755e8ab5149f' and md5(dataset) = '1812af399ccc40505ad5c2c3b72c5815' and fields = '[{"key": "obodo_horner_k_md", "tol": 0.05, "unit": "mD", "label": "OBODO-4 Horner permeability", "expected": 40.34569148966339}, {"key": "obodo_horner_skin", "tol": 0.005, "unit": "-", "label": "OBODO-4 skin from the one-hour pressure", "expected": 2.782737573136271}, {"key": "obodo_slope_psi_cycle", "tol": 0.005, "unit": "psi/cycle", "label": "OBODO-4 semilog slope", "expected": 61.82280952202884}, {"key": "obodo_pstar_psia", "tol": 0.05, "unit": "psia", "label": "OBODO-4 extrapolated pressure p star", "expected": 5200.545328117058}, {"key": "obodo_skin_dp_psi", "tol": 0.05, "unit": "psi", "label": "OBODO-4 skin pressure drop", "expected": 149.39468435825378}, {"key": "obodo_ri_at_tp_ft", "tol": 0.5, "unit": "ft", "label": "OBODO-4 radius of investigation at 48 h", "expected": 824.778564872257}]'::jsonb then 'new'
              else 'other' end
    into v_s0 from public.academy_capstones where app_slug = 'welltest' and tier = 'beginner' and active;
  if v_s0 = 'other' then
    raise exception 'w5c welltest refused: welltest/beginner matches neither its post-W1 form (prompt md5 5f4d6e8c2f85acf547e09db4e46cb256) nor its W5 form (prompt md5 959c0a681647ab6f0014755e8ab5149f), with the dataset and fields this file was generated against';
  end if;

  -- welltest / intermediate
  select count(*) into v_n from public.academy_capstones where app_slug = 'welltest' and tier = 'intermediate' and active;
  if v_n <> 1 then raise exception 'w5c welltest refused: welltest/intermediate has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = 'e9a37660798a517b1ff9ef1952d9a13a' and md5(dataset) = 'c7b292d828ae78170fc3bfa48982dc99' and fields = '[{"key": "radial_plateau_psi", "tol": 0.005, "unit": "psi", "label": "Buildup radial derivative plateau", "expected": 9.590852793412228}, {"key": "fault_late_k_md", "tol": 0.05, "unit": "mD", "label": "Permeability from the late line", "expected": 45.25748634072017}, {"key": "fault_slope_ratio", "tol": 0.002, "unit": "-", "label": "Late slope over early slope", "expected": 1.795381509640958}, {"key": "fracture_sqrt_slope", "tol": 0.005, "unit": "psi/sqrt(h)", "label": "Linear-flow sqrt-time slope", "expected": 51.502350529498294}, {"key": "rect_drainage_area_ft2", "tol": 50, "unit": "ft2", "label": "Drainage area", "expected": 2800109.0707769613}, {"key": "dp_dip_ratio", "tol": 0.0005, "unit": "-", "label": "Derivative dip over late plateau", "expected": 0.27750746082216926}]'::jsonb then 'old'
              when md5(prompt) = '8db0da68e961136b890c7148d4cafa9d' and md5(dataset) = 'c7b292d828ae78170fc3bfa48982dc99' and fields = '[{"key": "radial_plateau_psi", "tol": 0.005, "unit": "psi", "label": "Buildup radial derivative plateau", "expected": 9.590852793412228}, {"key": "fault_late_k_md", "tol": 0.05, "unit": "mD", "label": "Permeability from the late line", "expected": 45.25748634072017}, {"key": "fault_slope_ratio", "tol": 0.002, "unit": "-", "label": "Late slope over early slope", "expected": 1.795381509640958}, {"key": "fracture_sqrt_slope", "tol": 0.005, "unit": "psi/sqrt(h)", "label": "Linear-flow sqrt-time slope", "expected": 51.502350529498294}, {"key": "rect_drainage_area_ft2", "tol": 50, "unit": "ft2", "label": "Drainage area", "expected": 2800109.0707769613}, {"key": "dp_dip_ratio", "tol": 0.0005, "unit": "-", "label": "Derivative dip over late plateau", "expected": 0.27750746082216926}]'::jsonb then 'new'
              else 'other' end
    into v_s1 from public.academy_capstones where app_slug = 'welltest' and tier = 'intermediate' and active;
  if v_s1 = 'other' then
    raise exception 'w5c welltest refused: welltest/intermediate matches neither its post-W1 form (prompt md5 e9a37660798a517b1ff9ef1952d9a13a) nor its W5 form (prompt md5 8db0da68e961136b890c7148d4cafa9d), with the dataset and fields this file was generated against';
  end if;

  -- welltest / advanced
  select count(*) into v_n from public.academy_capstones where app_slug = 'welltest' and tier = 'advanced' and active;
  if v_n <> 1 then raise exception 'w5c welltest refused: welltest/advanced has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = '8a397877a9426d217d9c1a4b4b99d617' and md5(dataset) = '10520dd57bf7cd46fa8c6813e40faf31' and fields = '[{"key": "fault_fit_distance_ft", "tol": 1.0, "unit": "ft", "label": "Fitted distance to the fault", "expected": 793.8937564207687}, {"key": "multirate_k_md", "tol": 0.05, "unit": "mD", "label": "Multi-rate semilog permeability", "expected": 83.40692632353809}, {"key": "equivalent_producing_time_h", "tol": 0.005, "unit": "hours", "label": "Equivalent producing time", "expected": 64.28571428571429}, {"key": "aof_disagreement_pct", "tol": 0.005, "unit": "percent", "label": "Back-pressure AOF over Houpeurt", "expected": 4.049138750335787}, {"key": "rta_oil_n_stb", "tol": 5, "unit": "stb", "label": "Oil in place, flowing MB", "expected": 1996864.3157109257}, {"key": "rta_gas_g_mscf", "tol": 50, "unit": "Mscf", "label": "Gas in place, dynamic MB", "expected": 19960373.229717568}]'::jsonb then 'old'
              when md5(prompt) = '93fe4310d601bd945d53d61664e601b1' and md5(dataset) = '10520dd57bf7cd46fa8c6813e40faf31' and fields = '[{"key": "fault_fit_distance_ft", "tol": 1.0, "unit": "ft", "label": "Fitted distance to the fault", "expected": 793.8937564207687}, {"key": "multirate_k_md", "tol": 0.05, "unit": "mD", "label": "Multi-rate semilog permeability", "expected": 83.40692632353809}, {"key": "equivalent_producing_time_h", "tol": 0.005, "unit": "hours", "label": "Equivalent producing time", "expected": 64.28571428571429}, {"key": "aof_disagreement_pct", "tol": 0.005, "unit": "percent", "label": "Back-pressure AOF over Houpeurt", "expected": 4.049138750335787}, {"key": "rta_oil_n_stb", "tol": 5, "unit": "stb", "label": "Oil in place, flowing MB", "expected": 1996864.3157109257}, {"key": "rta_gas_g_mscf", "tol": 50, "unit": "Mscf", "label": "Gas in place, dynamic MB", "expected": 19960373.229717568}]'::jsonb then 'new'
              else 'other' end
    into v_s2 from public.academy_capstones where app_slug = 'welltest' and tier = 'advanced' and active;
  if v_s2 = 'other' then
    raise exception 'w5c welltest refused: welltest/advanced matches neither its post-W1 form (prompt md5 8a397877a9426d217d9c1a4b4b99d617) nor its W5 form (prompt md5 93fe4310d601bd945d53d61664e601b1), with the dataset and fields this file was generated against';
  end if;

  -- nothing to write: every row is already in its W5 form
  if v_s0 = 'new' and v_s1 = 'new' and v_s2 = 'new' then
    raise notice 'w5c welltest: 0 of 3 row(s) written, all already applied';
    return;
  end if;

  -- ATTEMPTS. A tier whose graded keys this file moves must hold no capstone
  -- attempt (a stored score is never re-scored, but a learner could be graded
  -- differently on a retry), unless D5 allowlists it with the exact attempt
  -- ids signed off. Any other attempt refuses.
  if v_s0 = 'old' then
    select coalesce(jsonb_agg(a.id::text order by a.created_at, a.id), '[]'::jsonb) into v_ids
      from public.academy_capstone_attempts a where a.app_slug = 'welltest' and a.tier = 'beginner';
    if jsonb_array_length(v_ids) > 0 then
      if v_allow ? 'welltest/beginner' then
        select coalesce(jsonb_agg(x), '[]'::jsonb) into v_extra
          from jsonb_array_elements(v_ids) x where not (v_allow->'welltest/beginner') @> jsonb_build_array(x);
        if jsonb_array_length(v_extra) > 0 then
          select string_agg(x #>> '{}', ', ') into v_idtxt from jsonb_array_elements(v_extra) x;
          raise exception 'w5c welltest refused: welltest/beginner holds % attempt(s) outside its D5 allowlist: %', jsonb_array_length(v_extra), v_idtxt;
        end if;
        raise notice 'w5c welltest: welltest/beginner holds % allowlisted attempt(s) (D5 sign-off); their stored scores are not touched', jsonb_array_length(v_ids);
      else
        select string_agg(x #>> '{}', ', ') into v_idtxt from jsonb_array_elements(v_ids) x;
        raise exception 'w5c welltest refused: welltest/beginner holds % capstone attempt(s) (%) and this file re-keys it; sign the tier off under D5 (allowlist with these ids) or hold it', jsonb_array_length(v_ids), v_idtxt;
      end if;
    end if;
  end if;

  if v_s0 = 'old' then
    update public.academy_capstones
       set prompt = 'Analyse the OBODO-4 pressure buildup and report six quantities from ONE fit. Download the buildup file from the capstone case files on this card (40 shut-in times in hours and pressures in psia) and open it in the buildup explorer''s Your test mode. The well produced at 620 stb/d for 48 hours and was shut in at a flowing pressure of 4640.818 psia; the reservoir has porosity 0.21, viscosity 1.3 cp, total compressibility 1.1e-5 per psi, wellbore radius 0.3 ft, net pay 62 ft and formation volume factor 1.18 rb/stb. Fit a Horner semilog line by least squares to the TEN points whose shut-in time is 8 hours or more, and report: the permeability that line implies; the skin, taking the line''s value at one hour of shut-in as the reference; the magnitude of the semilog slope in psi per cycle; the pressure the line extrapolates to at a Horner ratio of one; the skin pressure drop, and the radius of investigation at the 48 hour producing time. The last two must use the permeability and skin YOU reported.',
           dataset = 'OBODO-4 buildup file (obodo4_buildup.csv, downloaded from the capstone card): 40 shut-in pressures after 48 h at 620 stb/d, pwf at shut-in 4640.818 psia',
           fields = '[{"key": "obodo_horner_k_md", "tol": 0.05, "unit": "mD", "label": "OBODO-4 Horner permeability", "expected": 40.34569148966339}, {"key": "obodo_horner_skin", "tol": 0.005, "unit": "-", "label": "OBODO-4 skin from the one-hour pressure", "expected": 2.782737573136271}, {"key": "obodo_slope_psi_cycle", "tol": 0.005, "unit": "psi/cycle", "label": "OBODO-4 semilog slope", "expected": 61.82280952202884}, {"key": "obodo_pstar_psia", "tol": 0.05, "unit": "psia", "label": "OBODO-4 extrapolated pressure p star", "expected": 5200.545328117058}, {"key": "obodo_skin_dp_psi", "tol": 0.05, "unit": "psi", "label": "OBODO-4 skin pressure drop", "expected": 149.39468435825378}, {"key": "obodo_ri_at_tp_ft", "tol": 0.5, "unit": "ft", "label": "OBODO-4 radius of investigation at 48 h", "expected": 824.778564872257}]'::jsonb
     where app_slug = 'welltest' and tier = 'beginner' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w5c welltest refused: welltest/beginner updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = '959c0a681647ab6f0014755e8ab5149f' and md5(dataset) = '1812af399ccc40505ad5c2c3b72c5815' and fields = '[{"key": "obodo_horner_k_md", "tol": 0.05, "unit": "mD", "label": "OBODO-4 Horner permeability", "expected": 40.34569148966339}, {"key": "obodo_horner_skin", "tol": 0.005, "unit": "-", "label": "OBODO-4 skin from the one-hour pressure", "expected": 2.782737573136271}, {"key": "obodo_slope_psi_cycle", "tol": 0.005, "unit": "psi/cycle", "label": "OBODO-4 semilog slope", "expected": 61.82280952202884}, {"key": "obodo_pstar_psia", "tol": 0.05, "unit": "psia", "label": "OBODO-4 extrapolated pressure p star", "expected": 5200.545328117058}, {"key": "obodo_skin_dp_psi", "tol": 0.05, "unit": "psi", "label": "OBODO-4 skin pressure drop", "expected": 149.39468435825378}, {"key": "obodo_ri_at_tp_ft", "tol": 0.5, "unit": "ft", "label": "OBODO-4 radius of investigation at 48 h", "expected": 824.778564872257}]'::jsonb) from public.academy_capstones where app_slug = 'welltest' and tier = 'beginner' and active) is not true then
    raise exception 'w5c welltest refused: welltest/beginner does not read back as its W5 form';
  end if;

  if v_s1 = 'old' then
    update public.academy_capstones
       set prompt = 'Diagnose four pressure transients and report one number from each, at the settings stated. Use a Bourdet smoothing window L of 0.1 throughout. (1) On the BUILDUP, differentiated against Agarwal equivalent time with the fixture''s own pressure change, report the arithmetic mean of the derivative over the twelve points whose equivalent time is 5 hours or more. (2) On the SEALING FAULT test, fit MDH semilog lines to the flowing pressures over 1 to 20 hours and over 200 to 1000 hours, and report the permeability the LATE line implies. (3) Report the ratio of that late line''s slope to the early line''s. (4) On the FRACTURED well, fit pressure change against the square root of time in hours over 0.1 to 10 hours and report the slope. (5) On the CLOSED RECTANGLE, fit flowing pressure against time over 500 hours and later, convert the Cartesian slope to a pore volume and divide by porosity times net pay, and report the drainage area in SQUARE FEET. (6) On the DUAL POROSITY test, report the minimum derivative between 0.05 and 50 hours divided by the mean derivative from 300 hours on.',
           dataset = 'four fixtures: the buildup, the sealing fault at 800 ft, the 250 ft fracture in 5 mD rock, the closed 2000 by 1400 ft rectangle, and the dual-porosity test at omega 0.08',
           fields = '[{"key": "radial_plateau_psi", "tol": 0.005, "unit": "psi", "label": "Buildup radial derivative plateau", "expected": 9.590852793412228}, {"key": "fault_late_k_md", "tol": 0.05, "unit": "mD", "label": "Permeability from the late line", "expected": 45.25748634072017}, {"key": "fault_slope_ratio", "tol": 0.002, "unit": "-", "label": "Late slope over early slope", "expected": 1.795381509640958}, {"key": "fracture_sqrt_slope", "tol": 0.005, "unit": "psi/sqrt(h)", "label": "Linear-flow sqrt-time slope", "expected": 51.502350529498294}, {"key": "rect_drainage_area_ft2", "tol": 50, "unit": "ft2", "label": "Drainage area", "expected": 2800109.0707769613}, {"key": "dp_dip_ratio", "tol": 0.0005, "unit": "-", "label": "Derivative dip over late plateau", "expected": 0.27750746082216926}]'::jsonb
     where app_slug = 'welltest' and tier = 'intermediate' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w5c welltest refused: welltest/intermediate updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = '8db0da68e961136b890c7148d4cafa9d' and md5(dataset) = 'c7b292d828ae78170fc3bfa48982dc99' and fields = '[{"key": "radial_plateau_psi", "tol": 0.005, "unit": "psi", "label": "Buildup radial derivative plateau", "expected": 9.590852793412228}, {"key": "fault_late_k_md", "tol": 0.05, "unit": "mD", "label": "Permeability from the late line", "expected": 45.25748634072017}, {"key": "fault_slope_ratio", "tol": 0.002, "unit": "-", "label": "Late slope over early slope", "expected": 1.795381509640958}, {"key": "fracture_sqrt_slope", "tol": 0.005, "unit": "psi/sqrt(h)", "label": "Linear-flow sqrt-time slope", "expected": 51.502350529498294}, {"key": "rect_drainage_area_ft2", "tol": 50, "unit": "ft2", "label": "Drainage area", "expected": 2800109.0707769613}, {"key": "dp_dip_ratio", "tol": 0.0005, "unit": "-", "label": "Derivative dip over late plateau", "expected": 0.27750746082216926}]'::jsonb) from public.academy_capstones where app_slug = 'welltest' and tier = 'intermediate' and active) is not true then
    raise exception 'w5c welltest refused: welltest/intermediate does not read back as its W5 form';
  end if;

